-- composition of rule kernels P:CombinePartialFinalAggregate x P:FilterPushdown (datafusion), template graft_exists
SELECT ' '::text AS c0, 0.0::float8 AS c1, 'abc'::text AS c2 FROM (SELECT * FROM tp WHERE EXISTS (SELECT 1 FROM (SELECT DISTINCT '0 days'::interval AS c0, make_array('a', 'b') AS c1, '1970-01-01'::date AS c2 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c3 = a2.c3)) WHERE COALESCE ((LENGTH ((SELECT STRING_AGG ('NaN'::text, ',' ORDER BY 'NaN'::text) FROM tp AS a3)) <> a2.c0), (a1.c0 IS DISTINCT FROM a2.c0))) AS kb) OR NOT EXISTS (SELECT 1 FROM (SELECT DISTINCT '0 days'::interval AS c0, make_array('a', 'b') AS c1, '1970-01-01'::date AS c2 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c3 = a2.c3)) WHERE COALESCE ((LENGTH ((SELECT STRING_AGG ('NaN'::text, ',' ORDER BY 'NaN'::text) FROM tp AS a3)) <> a2.c0), (a1.c0 IS DISTINCT FROM a2.c0))) AS kb)) AS a1 WHERE (('2000-01-01'::date BETWEEN '1970-01-01'::date AND '1970-01-01'::date) OR (EXTRACT (MICROSECONDS FROM (SELECT MIN ('2000-01-01 00:00:00+00'::timestamptz) FROM t3 AS a2)) IS NULL));
